/** Binding facts shared by authored operations and their string-backed IR. */
import { isVarIR } from "./ir.js";
import { walkValueTree } from "./value-tree.js";
function variablesIn(value, backing) {
    const found = [];
    walkValueTree(value, (node) => {
        if (backing === "authored") {
            if (typeof node === "symbol")
                found.push(node);
        }
        else if (isVarIR(node)) {
            found.push(node.$var);
            return false;
        }
    });
    return found;
}
/** Every `{ $var }` name an IR pattern reads through, deep. */
export function varNamesInPattern(pattern) {
    return variablesIn(pattern, "ir");
}
/** Every variable an authored pattern reads through, deep. */
export function symbolsInMapping(mapping) {
    return variablesIn(mapping, "authored");
}
export function operationFootprint(op, backing) {
    const names = (value) => variablesIn(value, backing);
    const footprint = (inputs, produces = [], negative = []) => ({
        inputs,
        requires: [...inputs, ...negative],
        produces,
        mentions: [...inputs, ...produces, ...negative],
        negative,
    });
    switch (op.op) {
        case "find":
        case "whether":
            return footprint(names(op.in), names(op.out), "not" in op && op.not !== undefined ? names(op.not) : []);
        case "no":
            return footprint(names(op.in), [], names(op.out));
        case "holds": {
            const input = backing === "authored"
                ? op.fused.in
                : op.in;
            return footprint(names(input));
        }
        case "compute":
            return footprint(names(op.in), typeof op.out === "string" || typeof op.out === "symbol" ? [op.out] : names(op.out));
        case "count":
            return footprint(names(op.in), [op.out]);
        case "now":
            return footprint([], [op.out]);
        case "custom":
            return footprint([...op.in], [...op.out]);
        case "earlier": {
            const pattern = backing === "authored"
                ? op.pattern
                : op.when;
            return footprint([], [...names(pattern.input), ...names(pattern.output)]);
        }
    }
}
